insert into public.learning_cards (lesson_id, position, title, blocks) values ('bd44bdc8-f15e-57b3-9d89-bfde64890a12', 1, 'La première console', '[{"type":"keyfigure","value":"1972","label":"Sortie de la Magnavox Odyssey, première console de salon"},{"type":"text","text":"Conçue par l’ingénieur Ralph Baer, l’Odyssey se branche sur la télévision. Les joueurs posent même des calques sur l’écran pour habiller les jeux."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('bd44bdc8-f15e-57b3-9d89-bfde64890a12', 2, 'Pong et Atari', '[{"type":"text","text":"La même année, Nolan Bushnell et Ted Dabney fondent Atari. Leur borne d’arcade Pong, programmée par Allan Alcorn, fait un tabac dans les bars."},{"type":"fact","text":"Pong imite le tennis de table : deux raquettes, une balle, et c’est tout."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('bd44bdc8-f15e-57b3-9d89-bfde64890a12', 3, 'Space Invaders', '[{"type":"text","text":"En 1978, Space Invaders de Taito, créé par Tomohiro Nishikado, remplit les salles d’arcade du monde entier."}]'::jsonb);
insert into public.lesson_items (lesson_id, position, question_id) values ('bd44bdc8-f15e-57b3-9d89-bfde64890a12', 1, 'dea7b5ee-8ec2-5060-abeb-58e1ac2771ba');
