insert into public.learning_cards (lesson_id, position, title, blocks) values ('ec188baf-09de-5a94-8767-c3ee2a031d29', 1, 'L’Atari 2600', '[{"type":"keyfigure","value":"1977","label":"Sortie de l’Atari 2600 (ou VCS)"},{"type":"text","text":"Ses cartouches interchangeables permettent d’acheter de nouveaux jeux : le jeu vidéo s’installe dans les foyers."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('ec188baf-09de-5a94-8767-c3ee2a031d29', 2, 'Le krach de 1983', '[{"type":"text","text":"Trop de consoles, trop de jeux bâclés : en 1983, le marché nord-américain s’effondre."},{"type":"fact","text":"Des cartouches invendues du jeu E.T. ont été enfouies dans le désert du Nouveau-Mexique, puis exhumées en 2014."}]'::jsonb);
