insert into public.learning_cards (lesson_id, position, title, blocks) values ('aea3b764-9657-5ff5-b084-2542cd4245e4', 1, 'Famicom et NES', '[{"type":"text","text":"Nintendo sort la Famicom au Japon en 1983, puis la NES aux États-Unis en 1985. Elle redonne confiance au marché."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('aea3b764-9657-5ff5-b084-2542cd4245e4', 2, 'Mario', '[{"type":"text","text":"Mario apparaît dans Donkey Kong en 1981. En 1985, Super Mario Bros., imaginé par Shigeru Miyamoto, devient une référence."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('aea3b764-9657-5ff5-b084-2542cd4245e4', 3, 'Le Game Boy', '[{"type":"keyfigure","value":"1989","label":"Sortie du Game Boy"},{"type":"text","text":"Conçu par l’équipe de Gunpei Yokoi, il est vendu avec Tetris, créé en 1984 à Moscou par Alexeï Pajitnov."}]'::jsonb);
