insert into public.learning_cards (lesson_id, position, title, blocks) values ('bba8b9b4-8124-5d2b-bb9a-de755e356d4e', 2, 'Sonic contre Mario', '[{"type":"text","text":"En 1991, Sega lance Sonic, hérisson bleu ultra-rapide pensé pour rivaliser avec Mario."},{"type":"fact","text":"La Super Nintendo, sortie au Japon en 1990 sous le nom de Super Famicom, répond coup pour coup."}]'::jsonb);
