insert into public.learning_cards (lesson_id, position, title, blocks) values ('201328d5-89b5-5450-a602-122ae35acfe1', 1, 'Une origine surprenante', '[{"type":"text","text":"Sony devait concevoir un lecteur CD pour la Super Nintendo. Nintendo abandonne le projet : Sony décide de faire sa propre console."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('201328d5-89b5-5450-a602-122ae35acfe1', 2, 'La PlayStation', '[{"type":"keyfigure","value":"1994","label":"Sortie de la PlayStation au Japon, le 3 décembre"},{"type":"text","text":"Ses jeux sur CD-ROM coûtent moins cher à produire. Ken Kutaragi, chez Sony, est considéré comme son père."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('201328d5-89b5-5450-a602-122ae35acfe1', 3, 'Un record', '[{"type":"fact","text":"La PlayStation est la première console de salon à dépasser les 100 millions d’exemplaires vendus."}]'::jsonb);
